void partial_final_scale(int16_t *des, const int16_t *src);

// in-place
void cyclic_mul_partial_CT_GS(int16_t *des, const int16_t *src1, const int16_t *src2);

void rader_17_primitive(int16_t *des, int16_t *src, int16_t *twiddle_table, int16_t *twiddle_inv_table, size_t jump);

void rader_17_primitive_inv(int16_t *des, int16_t *src, int16_t *twiddle_inv_table, int16_t *twiddle_table, size_t jump);

int main(void){

    int16_t twiddle17[17];
    int16_t twiddle_buff[128];
    int16_t twist[16 * 96];
    int16_t twist_extended[2 * 16 * 96];
    int16_t twiddle, t, omega;

// ================

    omega = OMEGA17;
    getExpVec(twiddle17, omega, 17);
    assert(memcmp(twiddle_rader17, twiddle17, 17 * sizeof(int16_t)) == 0);

    rader_17_primitive_twiddle_permute(twiddle_buff, twiddle_rader17);

    for(size_t i = 0; i < 8; i++){
        add_sub(twiddle_buff + i + 0, twiddle_buff + i + 8);
    }
    for(size_t i = 0; i < 4; i++){
        add_sub(twiddle_buff + i + 0, twiddle_buff + i + 4);
    }
    assert(memcmp(twiddle_rader17_permuted, twiddle_buff, 16 * sizeof(int16_t)) == 0);

    printf("Primitive Rader-17 twiddle table finished!\n");

// ================

    omega = OMEGA17INV;
    getExpVec(twiddle17, omega, 17);
    assert(memcmp(twiddle_rader17_inv, twiddle17, 17 * sizeof(int16_t)) == 0);

    t = 1;
    for(size_t i = 0; i < 17; i++){
        ring_h.subZ(twiddle17 + i, twiddle_rader17 + i, &t);
    }
    assert(memcmp(twiddle_inv_rader17, twiddle17, 17 * sizeof(int16_t)) == 0);

    rader_17_primitive_inv_twiddle_permute(twiddle_buff, twiddle_inv_rader17);

    for(size_t i = 0; i < 8; i++){
        add_sub(twiddle_buff + i + 0, twiddle_buff + i + 8);
    }
    for(size_t i = 0; i < 4; i++){
        add_sub(twiddle_buff + i + 0, twiddle_buff + i + 4);
    }

    assert(memcmp(twiddle_irader17_permuted, twiddle_buff, 16 * sizeof(int16_t)) == 0);

    printf("Primitive Rader-17 inv twiddle table finished!\n");

// ================

    for(size_t i = 0; i < 16; i++){
        twiddle = twiddle_rader17[i + 1];
        ring_h.expZ(&twiddle, &twiddle, 14);
        twist[i * 96 + 0] = 1;
        for(size_t j = 1; j < 96; j++){
            ring_h.mulZ(twist + i * 96 + j, twist + i * 96 + (j - 1), &twiddle);
        }
    }
    for(size_t i = 0; i < 16; i++){
        for(size_t j = 0; j < 96; j++){
            ring_h.mulZ(twist + i * 96 + j, twist + i * 96 + j, twiddle_rader17_inv + i + 1);
        }
    }
    assert(memcmp(twist_table, twist, 1536 * sizeof(int16_t)) == 0);

    extend_table_int16(twist_extended, twist, 1536);
    for(size_t i = 0; i < 3072; i += 16){
        permute_table_lohi(twist_extended + i, 16);
    }
    assert(memcmp(twist_table_lohi, twist_extended, 3072 * sizeof(int16_t)) == 0);

    printf("Primitive Rader-17 + x^96 - w_17^i twist table finished!\n");

// ================

    for(size_t i = 0; i < 16; i++){
        twiddle = twiddle_rader17_inv[i + 1];
        ring_h.expZ(&twiddle, &twiddle, 14);
        twist[i * 96 + 0] = 1;
        for(size_t j = 1; j < 96; j++){
            ring_h.mulZ(twist + i * 96 + j, twist + i * 96 + (j - 1), &twiddle);
        }
    }
    for(size_t i = 0; i < 16; i++){
        for(size_t j = 0; j < 96; j++){
            ring_h.mulZ(twist + i * 96 + j, twist + i * 96 + j, twiddle_rader17 + i + 1);
        }
    }
    assert(memcmp(twist_inv_table, twist, 1536 * sizeof(int16_t)) == 0);

    extend_table_int16(twist_extended, twist, 1536);
    for(size_t i = 0; i < 3072; i += 16){
        permute_table_lohi(twist_extended + i, 16);
    }
    assert(memcmp(twist_inv_table_lohi, twist_extended, 3072 * sizeof(int16_t)) == 0);

    printf("Primitive Rader-17 + x^96 - w_17^i inverse twist table finished!\n");

// ================

    for(size_t i = 0; i < 32 * 48; i += 48){
        memmove(twist + i + 0 * 16,  twist16id, 16 * sizeof(int16_t));
        memmove(twist + i + 1 * 16,    twist16, 16 * sizeof(int16_t));
        memmove(twist + i + 2 * 16, twist16inv, 16 * sizeof(int16_t));
    }
    assert(memcmp(twist_16x6x16_table, twist, 1536 * sizeof(int16_t)) == 0);

    extend_table_int16(twist_extended, twist, 1536);
    for(size_t i = 0; i < 3072; i += 16){
        permute_table_lohi(twist_extended + i, 16);
    }
    assert(memcmp(twist_16x6x16_table_lohi, twist_extended, 1536 * sizeof(int16_t)) == 0);

    printf("Full size-6 twist table finished!\n");

// ================

    for(size_t i = 0; i < 32 * 48; i += 48){
        memmove(twist + i + 0 * 16,  twist16id, 16 * sizeof(int16_t));
        memmove(twist + i + 1 * 16, twist16inv, 16 * sizeof(int16_t));
        memmove(twist + i + 2 * 16,    twist16, 16 * sizeof(int16_t));
    }
    assert(memcmp(twist_16x6x16_inv_table, twist, 1536 * sizeof(int16_t)) == 0);

    extend_table_int16(twist_extended, twist, 1536);
    for(size_t i = 0; i < 3072; i += 16){
        permute_table_lohi(twist_extended + i, 16);
    }
    assert(memcmp(twist_16x6x16_inv_table_lohi, twist_extended, 1536 * sizeof(int16_t)) == 0);

    printf("Full size-6 inverse twist table finished!\n");

    printf("Table generation finished!\n");

}

void getExpVec(int16_t *des, int16_t w, size_t len){

    des[0] = 1;
    for(size_t i = 1; i < len; i++){
        ring_h.mulZ(des + i, des + i - 1, &w);
    }

}

int16_t gethi(int16_t a){

    int16_t scale;

    scale = RmodQ;

    ring_h.mulZ(&a, &a, &scale);

    if((a & 1) == 0){
        if(a < 0){
            a += Q;
        }
        if(a > 0){
            a -= Q;
        }
    }

    a *= Qprime;
    a >>= 1;

    return a;

}

void extend_table_int16(int16_t *table_extended, int16_t *table, size_t len){

    for(size_t i = 0; i < len; i++){
        table_extended[2 * i + 0] = table[i];
        table_extended[2 * i + 1] = gethi(table[i]);
    }

}

void permute_table_lohi(int16_t *table, size_t len){

    int16_t buff[len];

    for(size_t i = 0; i < (len / 2); i++){
        buff[i + 0 * (len / 2)] = table[2 * i + 0];
        buff[i + 1 * (len / 2)] = table[2 * i + 1];
    }

    memmove(table, buff, len * sizeof(int16_t));

}

// out-of-place
void rader_17_primitive_twiddle_permute(int16_t *des, const int16_t *src){
    for(size_t i = 0; i < 16; i++){
        des[rader_dlog_permute[i]] = src[i + 1];
    }
}

// in-place
void rader_17_primitive_inv_twiddle_permute(int16_t *des, const int16_t *src){
    int16_t buff[16];
    rader_17_primitive_twiddle_permute(buff, src);
    for(size_t i = 0; i < 8; i++){
        des[i] = buff[7 - i];
    }
    for(size_t i = 8; i < 16; i++){
        des[i] = buff[23 - i];
    }

}

// in-place
void add_sub(int16_t *a, int16_t *b){
    int16_t t = *a;
    ring_h.addZ(a, &t, b);
    ring_h.subZ(b, &t, b);
}

// in-place
void partial_cyclic_CT(int16_t *des, const int16_t *src){
    for(size_t i = 0; i < 16; i++){
        des[i] = src[i];
    }
    for(size_t i = 0; i < 8; i++){
        add_sub(des + i, des + i + 8);
    }
    for(size_t i = 0; i < 4; i++){
        add_sub(des + i, des + i + 4);
    }
    for(size_t i = 0; i < 2; i++){
        add_sub(des + i, des + i + 2);
    }
    add_sub(des + 0, des + 1);
}

// in-place
void partial_cyclic_GS(int16_t *des, const int16_t *src){
    for(size_t i = 0; i < 16; i++){
        des[i] = src[i];
    }
    add_sub(des + 0, des + 1);
    for(size_t i = 0; i < 2; i++){
        add_sub(des + i, des + i + 2);
    }
    for(size_t i = 0; i < 4; i++){
        add_sub(des + i, des + i + 4);
    }
    for(size_t i = 0; i < 8; i++){
        add_sub(des + i, des + i + 8);
    }
}

// in-place
void partial_cyclic_negacyclic_mul(int16_t *des, const int16_t *src1, const int16_t *src2){

    int16_t twiddle = -1;

    ring_h.mulZ(des + 0, src1 + 0, src2 + 0);
    ring_h.mulZ(des + 1, src1 + 1, src2 + 1);
    naive_mulR(des + 2, src1 + 2, src2 + 2, 2, &twiddle, ring_h);
    naive_mulR(des + 4, src1 + 4, src2 + 4, 4, &twiddle, ring_h);
    naive_mulR(des + 8, src1 + 8, src2 + 8, 8, &twiddle, ring_h);

}

// in-place
void partial_scale(int16_t *des, const int16_t *src){
    int16_t scale;
    for(size_t i = 0; i < 2; i++){
        des[i] = src[i];
    }
    scale = 2;
    for(size_t i = 2; i < 4; i++){
        ring_h.mulZ(des + i, src + i, &scale);
    }
    scale = 4;
    for(size_t i = 4; i < 8; i++){
        ring_h.mulZ(des + i, src + i, &scale);
    }
    scale = 8;
    for(size_t i = 8; i < 16; i++){
        ring_h.mulZ(des + i, src + i, &scale);
    }
}

// in-place
void partial_final_scale(int16_t *des, const int16_t *src){
    int16_t scale = INV16;
    for(size_t i = 0; i < 16; i++){
        ring_h.mulZ(des + i, src + i, &scale);
    }
}

// in-place
void cyclic_mul_partial_CT_GS(int16_t *des, const int16_t *src1, const int16_t *src2){

    int16_t buff1[16], buff2[16];

    partial_cyclic_CT(buff1, src1);
    partial_cyclic_CT(buff2, src2);
    partial_cyclic_negacyclic_mul(des, buff1, buff2);
    partial_scale(des, des);
    partial_cyclic_GS(des, des);
    partial_final_scale(des, des);

}

void rader_17_primitive(int16_t *des, int16_t *src, int16_t *twiddle_table, int16_t *twiddle_inv_table, size_t jump){

    int16_t twiddle_permuted[16];
    int16_t src_permuted[16];

    for(size_t i = 0; i < 16; i++){
        src_permuted[(16 - rader_dlog_permute[i]) % 16] = src[i * jump];
    }

    // We can precompute the following for the twiddle factors.
    rader_17_primitive_twiddle_permute(twiddle_permuted, twiddle_table);
    partial_cyclic_CT(twiddle_permuted, twiddle_permuted);
    partial_scale(twiddle_permuted, twiddle_permuted);

    partial_cyclic_CT(src_permuted, src_permuted);
    partial_cyclic_negacyclic_mul(src_permuted, src_permuted, twiddle_permuted);
    partial_cyclic_GS(src_permuted, src_permuted);
    // This scaling can be postponed.
    partial_final_scale(src_permuted, src_permuted);

    rader_17_primitive_twiddle_permute(twiddle_permuted, twiddle_inv_table);

    // This point_mul can be merged with twisting.
    point_mul(src_permuted, src_permuted, twiddle_permuted, 16, 1, ring_h);

    for(size_t i = 0; i < 16; i++){
        des[i * jump] = src_permuted[rader_dlog_permute[i]];
    }

}


